export const prototypeLevel={id:'guild-prototype-fidelity',number:'826',kind:'prototype-fidelity',name:'三つの試作工房',tag:'試作の粒度と目的',title:'調べたいことに合う試作品を選ぼう',story:'祭りの受付を作る前に、紙の札、動く模型、見た目を仕上げた絵を試します。時間と調べたい内容に合わせて選びましょう。'};
export const prototypeOptions={paper:{name:'紙の札',time:1,description:'大まかな情報の並びを話し合える。実際のキーボード操作や読み上げは試せない。'},interactive:{name:'動く受付の模型',time:3,description:'この模型では受付ボタンと移動順を試せる。完成品の安全性や実際の読み上げ対応を保証しない。'},polished:{name:'見た目を仕上げた静止画',time:6,description:'色や形の細部を見せられる。静止画なので実際の操作や移動順は試せない。'}};
export const prototypeScenes={early:{name:'最初の相談',goal:'情報の並びを話し合う',budget:2,best:'paper'},later:{name:'操作を確かめる',goal:'ボタンとキーボードの移動順を試す',budget:4,best:'interactive'}};
const validBoard=b=>Array.isArray(b)&&b.length===9&&b.every(v=>typeof v==='boolean');
export function sketchCreate(){return {board:Array(9).fill(false),history:[],slots:{a:null,b:null}};}
export function sketchToggle(q,index){if(!Number.isInteger(index)||index<0||index>=9)throw new RangeError('升目が不正です');q.history=[...q.history,q.board.slice()].slice(-30);q.board=q.board.map((v,i)=>i===index?!v:v);}
export function sketchUndo(q){if(!q.history.length)return false;q.board=q.history.pop();return true;}
export function sketchSave(q,slot){if(!['a','b'].includes(slot))throw new RangeError('案が不正です');q.slots[slot]=q.board.slice();}
export function sketchLoad(q,slot){if(!['a','b'].includes(slot)||!q.slots[slot])throw new RangeError('保存された案がありません');q.history=[...q.history,q.board.slice()].slice(-30);q.board=q.slots[slot].slice();}
export function sketchRestore(q){if(q===undefined)return sketchCreate();if(!q||!validBoard(q.board)||!Array.isArray(q.history)||q.history.length>30||q.history.some(b=>!validBoard(b))||!q.slots||!['a','b'].every(k=>q.slots[k]===null||validBoard(q.slots[k])))throw new RangeError('試作の記録が不正です');return {board:q.board.slice(),history:q.history.map(b=>b.slice()),slots:{a:q.slots.a?.slice()??null,b:q.slots.b?.slice()??null}};}
export function prototypeCreate(){return {scene:'early',inspected:{early:[],later:[]},choices:{early:null,later:null},answer:null,sketch:sketchCreate()};}
export function prototypeStep(q,action){if(typeof action!=='string')throw new RangeError('操作が不正です。');const [op,id,...extra]=action.split(':');if(extra.length||!Object.hasOwn(prototypeOptions,id))throw new RangeError('操作が不正です。');if(op==='inspect'){if(q.inspected[q.scene].includes(id))throw new RangeError('この試作品は確認しました。');q.inspected[q.scene].push(id);return;}if(op==='choose'){if(q.inspected[q.scene].length!==3)throw new RangeError('３つの試作品を確認しましょう。');q.choices[q.scene]=id;return;}throw new RangeError('操作が不正です。');}
export function prototypeComplete(q){return Object.entries(prototypeScenes).every(([id,scene])=>q.inspected[id].length===3&&q.choices[id]===scene.best)&&q.answer==='purpose';}
export function prototypeRestore(q){if(!q||!Object.hasOwn(prototypeScenes,q.scene)||!q.inspected||!q.choices||![null,'purpose','always','production'].includes(q.answer))throw new RangeError('記録が不正です。');const n=prototypeCreate();n.sketch=sketchRestore(q.sketch);n.scene=q.scene;n.answer=q.answer;for(const id of Object.keys(prototypeScenes)){const seen=q.inspected[id],choice=q.choices[id];if(!Array.isArray(seen)||new Set(seen).size!==seen.length||seen.some(x=>!Object.hasOwn(prototypeOptions,x))||![null,...Object.keys(prototypeOptions)].includes(choice)||(choice!==null&&seen.length!==3))throw new RangeError('記録が不正です。');n.inspected[id]=[...seen];n.choices[id]=choice;}return n;}
